{
  "problem": "Solve for n: 7 - 3n = 2(n + 4). (Resuelve la ecuación para n.)",
  "answer": "-1/5",
  "solution_steps": [
    "Distribute the 2 on the right side: 7 - 3n = 2n + 8.",
    "Move all terms containing n to one side and constant terms to the other: -3n - 2n = 8 - 7.",
    "Combine like terms: -5n = 1.",
    "Divide both sides by -5 to isolate n: n = 1 / -5 = -1/5."
  ]
}

